export fn permutation_and_combination(v:[*c]const i64,n:usize)i64{if(v==null or n!=3)return -1;const op=v[0];const num=v[1];const r=v[2];if(op<0 or op>2 or num<0 or num>18)return -1;if(op!=0 and (r<0 or r>num))return -1;var result:i64=1;if(op==0){var i:i64=2;while(i<=num):(i+=1)result*=i;}else if(op==1){var i=num-r+1;while(i<=num):(i+=1)result*=i;}else{var k=r;if(k>num-k)k=num-k;var i:i64=1;while(i<=k):(i+=1)result=result*(num-k+i)/i;}return result;}
